// facets lists p's set attributes in definition order.
func (p Partial) facets() ([]wattdb.Facet, error) {
	m, err := p.encode()
	if err != nil {
		return nil, err
	}
	var out []wattdb.Facet
	for _, f := range inputOrder {
		if av, ok := m[f]; ok {
			out = append(out, wattdb.Facet{Name: f, Value: av})
		}
	}
	return out, nil
}

